// AUTO-GENERATED by scripts/gen-vba.ts from src/server/excel/vba — do not edit by hand.
export const VBA_SOURCES: Record<string, string> = {
  "ThisWorkbook": "Option Explicit\n\nPrivate Sub Workbook_Open()\n    On Error GoTo Fail\n    EnsureControlButton\n    ThisWorkbook.Worksheets(CONTROL_SHEET).Activate\n    Exit Sub\nFail:\n    ' Opening must never be blocked by cosmetic problems; the issue is recorded instead.\n    LogError \"ThisWorkbook\", \"Workbook_Open\", \"OPEN\", Err.Number & \": \" & Err.Description, \"WARNING\"\nEnd Sub\n",
  "modBuffet": "'==============================================================================\n' modBuffet :: Buffet cost (module NOT_AVAILABLE until Phase 2; headers only)\n' By design the cost calculations for this area run on the HotelCost server (one\n' cost engine shared with the web application, spec 149). This module only lists\n' the datasets of its area so modReport writes them in a predictable order.\n'==============================================================================\nOption Explicit\n\nPublic Function BuffetSections() As Variant\n    BuffetSections = Array(\"buffetCost\", \"buffetSummary\", \"buffetProduct\")\nEnd Function\n",
  "modCharts": "'==============================================================================\n' modCharts :: rebuilds dashboard charts on 53_DASHBOARD_CHARTS from report tables.\n'==============================================================================\nOption Explicit\n\nPrivate Const XL_LINE As Long = 4\nPrivate Const XL_COLUMN_CLUSTERED As Long = 51\nPrivate Const XL_BAR_CLUSTERED As Long = 57\nPrivate Const CHART_SHEET As String = \"53_DASHBOARD_CHARTS\"\nPrivate Const W As Double = 470\nPrivate Const H As Double = 260\n\nPublic Sub RefreshCharts()\n    Dim ws As Worksheet\n    Dim i As Long\n    Set ws = ThisWorkbook.Worksheets(CHART_SHEET)\n    For i = ws.ChartObjects.Count To 1 Step -1\n        ws.ChartObjects(i).Delete\n    Next i\n    For i = ws.Shapes.Count To 1 Step -1\n        If Left$(ws.Shapes(i).Name, 4) = \"txt_\" Then ws.Shapes(i).Delete\n    Next i\n    LineChart ws, \"Cost Trend (actual vs theoretical)\", \"tbl_costTrend\", \"Month\", Array(\"Actual Cost\", \"Theoretical Cost\"), 10, 60, False\n    LineChart ws, \"Food Cost % Trend\", \"tbl_costTrend\", \"Month\", Array(\"Actual Cost %\", \"Theoretical Cost %\"), 10 + W + 20, 60, True\n    LineChart ws, \"Waste % Trend\", \"tbl_costTrend\", \"Month\", Array(\"Waste %\"), 10, 60 + H + 20, True\n    LineChart ws, \"Stock Value (month end)\", \"tbl_costTrend\", \"Month\", Array(\"Stock Value (month end)\"), 10 + W + 20, 60 + H + 20, False\n    BarChart ws, \"Department Cost\", \"tbl_departmentCost\", \"Department\", \"Total Cost\", 10, 60 + 2 * (H + 20), 15\n    BarChart ws, \"Top Cost Drivers (PPV)\", \"tbl_topCostDrivers\", \"Product\", \"Cost Increase (PPV)\", 10 + W + 20, 60 + 2 * (H + 20), 10\n    BarChart ws, \"Top Waste Products\", \"tbl_topWaste\", \"Product\", \"Waste Cost\", 10, 60 + 3 * (H + 20), 10\n    PriceTrendChart ws, 10 + W + 20, 60 + 3 * (H + 20)\n    NotAvailable ws, \"Room Cost / Occupied Night\", 10, 60 + 4 * (H + 20)\n    LineChart ws, \"Buffet Cost / Cover\", \"tbl_buffetCost\", \"Date\", Array(\"Cost / Cover\", \"Waste / Cover\"), 10 + W + 20, 60 + 4 * (H + 20), False\nEnd Sub\n\nPrivate Function HasData(ByVal lo As ListObject) As Boolean\n    HasData = False\n    If lo Is Nothing Then Exit Function\n    If lo.DataBodyRange Is Nothing Then Exit Function\n    HasData = Application.WorksheetFunction.CountA(lo.DataBodyRange) > 0\nEnd Function\n\nPrivate Sub LineChart(ByVal ws As Worksheet, ByVal title As String, ByVal tableName As String, ByVal xCol As String, _\n                      ByVal yCols As Variant, ByVal x As Double, ByVal y As Double, ByVal isPct As Boolean)\n    Dim lo As ListObject\n    Dim ch As Chart\n    Dim s As Variant\n    Dim ser As Object\n    On Error GoTo Fail\n    Set lo = FindTable(tableName)\n    If Not HasData(lo) Then\n        NotAvailable ws, title & \" (no data)\", x, y\n        Exit Sub\n    End If\n    Set ch = ws.ChartObjects.Add(x, y, W, H).Chart\n    ch.ChartType = XL_LINE\n    For Each s In yCols\n        Set ser = ch.SeriesCollection.NewSeries\n        ser.Name = CStr(s)\n        ser.Values = lo.ListColumns(CStr(s)).DataBodyRange\n        ser.XValues = lo.ListColumns(xCol).DataBodyRange\n    Next s\n    ch.HasTitle = True\n    ch.ChartTitle.Text = title\n    If isPct Then ch.Axes(2).TickLabels.NumberFormat = \"0.0%\"\n    Exit Sub\nFail:\n    LogError \"modCharts\", title, \"CHART\", Err.Number & \": \" & Err.Description, \"WARNING\"\nEnd Sub\n\nPrivate Sub BarChart(ByVal ws As Worksheet, ByVal title As String, ByVal tableName As String, ByVal labelCol As String, _\n                     ByVal valueCol As String, ByVal x As Double, ByVal y As Double, ByVal topN As Long)\n    Dim lo As ListObject\n    Dim ch As Chart\n    Dim ser As Object\n    Dim n As Long\n    On Error GoTo Fail\n    Set lo = FindTable(tableName)\n    If Not HasData(lo) Then\n        NotAvailable ws, title & \" (no data)\", x, y\n        Exit Sub\n    End If\n    n = lo.ListRows.Count\n    If n > topN Then n = topN\n    Set ch = ws.ChartObjects.Add(x, y, W, H).Chart\n    ch.ChartType = XL_BAR_CLUSTERED\n    Set ser = ch.SeriesCollection.NewSeries\n    ser.Name = valueCol\n    ser.Values = lo.ListColumns(valueCol).DataBodyRange.Resize(n)\n    ser.XValues = lo.ListColumns(labelCol).DataBodyRange.Resize(n)\n    ch.HasTitle = True\n    ch.ChartTitle.Text = title\n    ch.HasLegend = False\n    Exit Sub\nFail:\n    LogError \"modCharts\", title, \"CHART\", Err.Number & \": \" & Err.Description, \"WARNING\"\nEnd Sub\n\n' Long-format table (Month, Product, Unit Cost) -> one series per product.\nPrivate Sub PriceTrendChart(ByVal ws As Worksheet, ByVal x As Double, ByVal y As Double)\n    Dim lo As ListObject\n    Dim ch As Chart\n    Dim products As Object\n    Dim r As Long\n    Dim p As Variant\n    Dim months As Object\n    Dim vals() As Variant, xs() As Variant\n    Dim i As Long\n    Dim ser As Object\n    On Error GoTo Fail\n    Set lo = FindTable(\"tbl_priceTrend\")\n    If Not HasData(lo) Then\n        NotAvailable ws, \"Ingredient Price Trend (no data)\", x, y\n        Exit Sub\n    End If\n    Set products = CreateObject(\"Scripting.Dictionary\")\n    For r = 1 To lo.ListRows.Count\n        p = CStr(lo.DataBodyRange.Cells(r, 2).Value)\n        If Not products.Exists(p) Then products.Add p, New Collection\n        products(p).Add r\n    Next r\n    Set ch = ws.ChartObjects.Add(x, y, W, H).Chart\n    ch.ChartType = XL_LINE\n    For Each p In products.Keys\n        ReDim vals(1 To products(p).Count)\n        ReDim xs(1 To products(p).Count)\n        For i = 1 To products(p).Count\n            xs(i) = lo.DataBodyRange.Cells(products(p)(i), 1).Value\n            vals(i) = lo.DataBodyRange.Cells(products(p)(i), 3).Value\n        Next i\n        Set ser = ch.SeriesCollection.NewSeries\n        ser.Name = CStr(p)\n        ser.Values = vals\n        ser.XValues = xs\n    Next p\n    ch.HasTitle = True\n    ch.ChartTitle.Text = \"Ingredient Price Trend (top spend)\"\n    Exit Sub\nFail:\n    LogError \"modCharts\", \"PriceTrend\", \"CHART\", Err.Number & \": \" & Err.Description, \"WARNING\"\nEnd Sub\n\nPrivate Sub NotAvailable(ByVal ws As Worksheet, ByVal title As String, ByVal x As Double, ByVal y As Double)\n    Dim shp As Shape\n    Set shp = ws.Shapes.AddTextbox(1, x, y, W, H)\n    shp.Name = \"txt_\" & ws.Shapes.Count\n    shp.TextFrame.Characters.Text = title & vbLf & vbLf & \"Module not yet available in HotelCost - no data is shown rather than estimated values.\"\n    shp.Line.ForeColor.RGB = RGB(213, 217, 226)\nEnd Sub\n",
  "modCostCalculation": "'==============================================================================\n' modCostCalculation :: Executive summary, cost detail, food/beverage cost, theoretical vs actual, unexplained variance, trends, P&L\n' By design the cost calculations for this area run on the HotelCost server (one\n' cost engine shared with the web application, spec 149). This module only lists\n' the datasets of its area so modReport writes them in a predictable order.\n'==============================================================================\nOption Explicit\n\nPublic Function CostSections() As Variant\n    CostSections = Array(\"costDetail\", \"executiveSummary\", \"monthlySummary\", \"foodCost\", \"beverageCost\", \"consumptionVariance\", \"unexplainedVariance\", \"theoreticalConsumption\", \"actualConsumption\", \"productSales\", \"topVariance\", \"topCostDrivers\", \"costTrend\", \"priceTrend\", \"pnl\")\nEnd Function\n",
  "modDataImport": "'==============================================================================\n' modDataImport :: authenticated HTTPS fetch of the versioned export contract.\n' Transport format: TSV rendering of exportVersion 1.x (no JSON library needed).\n' Numbers arrive as invariant decimal strings and are converted with Val(),\n' which is locale-independent (works with Turkish decimal comma settings).\n'==============================================================================\nOption Explicit\n\nPrivate mToken As String\n\nPublic Function ApiToken() As String\n    If Len(mToken) = 0 Then mToken = Environ$(\"HOTELCOST_TOKEN\")\n    If Len(mToken) = 0 Then\n        mToken = InputBox(\"Paste your HotelCost API token (web app > Excel Export > Create token).\" & vbCrLf & _\n                          \"It is kept in memory only and is never saved in this workbook.\", \"HotelCost API token\")\n    End If\n    ApiToken = Trim$(mToken)\nEnd Function\n\nPublic Sub ForgetToken()\n    mToken = vbNullString\nEnd Sub\n\nPublic Function BuildExportUrl() As String\n    Dim baseUrl As String\n    baseUrl = Trim$(CStr(CtlValue(\"ctl_ApiUrl\")))\n    If Right$(baseUrl, 1) = \"/\" Then baseUrl = Left$(baseUrl, Len(baseUrl) - 1)\n    BuildExportUrl = baseUrl & \"/api/export/full-cost?format=tsv\" & _\n        \"&hotelId=\" & UrlEncode(CStr(CtlValue(\"ctl_HotelId\"))) & _\n        \"&from=\" & Format$(CtlValue(\"ctl_StartDate\"), \"yyyy-mm-dd\") & _\n        \"&to=\" & Format$(CtlValue(\"ctl_EndDate\"), \"yyyy-mm-dd\") & _\n        \"&departmentId=\" & UrlEncode(SelectedDepartmentId()) & _\n        \"&warehouseId=\" & UrlEncode(LookupId(\"tbl_lstWarehouses\", CStr(CtlValue(\"ctl_Warehouse\")))) & _\n        \"&group=\" & UrlEncode(CategoryParam(CStr(CtlValue(\"ctl_Category\"))))\nEnd Function\n\n' Department wins; if Department is \"All\" the Outlet selection is used.\nPublic Function SelectedDepartmentId() As String\n    SelectedDepartmentId = LookupId(\"tbl_lstDepartments\", CStr(CtlValue(\"ctl_Department\")))\n    If Len(SelectedDepartmentId) = 0 Then SelectedDepartmentId = LookupId(\"tbl_lstDepartments\", CStr(CtlValue(\"ctl_Outlet\")))\nEnd Function\n\nPrivate Function CategoryParam(ByVal v As String) As String\n    If UCase$(v) = \"ALL\" Or Len(v) = 0 Then CategoryParam = \"\" Else CategoryParam = UCase$(v)\nEnd Function\n\n' Lookup \"name -> id\" in a two-column hidden list table (name, id). \"All\" -> \"\".\nPublic Function LookupId(ByVal tableName As String, ByVal displayName As String) As String\n    Dim lo As ListObject\n    Dim r As Long\n    LookupId = \"\"\n    If Len(displayName) = 0 Or LCase$(Left$(displayName, 3)) = \"all\" Then Exit Function\n    Set lo = FindTable(tableName)\n    If lo Is Nothing Then Exit Function\n    If lo.DataBodyRange Is Nothing Then Exit Function\n    For r = 1 To lo.DataBodyRange.Rows.Count\n        If CStr(lo.DataBodyRange.Cells(r, 1).Value) = displayName Then\n            LookupId = CStr(lo.DataBodyRange.Cells(r, 2).Value)\n            Exit Function\n        End If\n    Next r\nEnd Function\n\nPublic Function UrlEncode(ByVal s As String) As String\n    Dim i As Long\n    Dim c As String\n    Dim code As Long\n    Dim out As String\n    For i = 1 To Len(s)\n        c = Mid$(s, i, 1)\n        code = AscW(c)\n        If (code >= 48 And code <= 57) Or (code >= 65 And code <= 90) Or (code >= 97 And code <= 122) Or c = \"-\" Or c = \"_\" Or c = \".\" Or c = \"~\" Then\n            out = out & c\n        Else\n            out = out & \"%\" & Right$(\"0\" & Hex$(code And &HFF), 2)\n        End If\n    Next i\n    UrlEncode = out\nEnd Function\n\n' Single attempt; returns True on transport success (any HTTP status).\nPrivate Function TryGet(ByVal url As String, ByVal token As String, ByRef httpStatus As Long, ByRef body As String, ByRef errText As String) As Boolean\n    Dim http As Object\n    On Error GoTo Fail\n    Set http = CreateObject(\"MSXML2.ServerXMLHTTP.6.0\")\n    http.setTimeouts 10000, 10000, 120000, 300000\n    http.Open \"GET\", url, False\n    http.setRequestHeader \"Authorization\", \"Bearer \" & token\n    http.setRequestHeader \"Accept\", \"text/tab-separated-values\"\n    http.send\n    httpStatus = http.Status\n    body = http.responseText\n    TryGet = True\n    Exit Function\nFail:\n    errText = Err.Number & \": \" & Err.Description\n    TryGet = False\nEnd Function\n\n' GET with safe retry/backoff for transient failures (network, 429, 5xx). 401/403/4xx fail fast.\nPublic Function HttpGetText(ByVal url As String) As String\n    Dim attempt As Long\n    Dim st As Long\n    Dim body As String\n    Dim errText As String\n    Dim token As String\n    token = ApiToken()\n    If Len(token) = 0 Then Err.Raise vbObjectError + 401, \"HttpGetText\", \"No API token provided.\"\n    For attempt = 1 To 4\n        st = 0: body = \"\": errText = \"\"\n        If TryGet(url, token, st, body, errText) Then\n            If st = 200 Then\n                HttpGetText = body\n                Exit Function\n            ElseIf st = 401 Or st = 403 Then\n                ForgetToken\n                Err.Raise vbObjectError + st, \"HttpGetText\", \"Access denied (HTTP \" & st & \"). Check the API token and your export permission.\"\n            ElseIf st <> 429 And st < 500 Then\n                Err.Raise vbObjectError + st, \"HttpGetText\", \"HotelCost API returned HTTP \" & st & \": \" & Left$(body, 300)\n            End If\n            errText = \"HTTP \" & st\n        End If\n        LogError \"modDataImport\", \"attempt \" & attempt, \"NETWORK\", errText, \"WARNING\"\n        If attempt < 4 Then Application.Wait Now + TimeSerial(0, 0, 2 ^ attempt)\n    Next attempt\n    Err.Raise vbObjectError + 503, \"HttpGetText\", \"HotelCost API unreachable after 4 attempts (\" & errText & \").\"\nEnd Function\n\n' Parses the TSV contract into a Dictionary:\n'   (\"meta\") -> Dictionary key->value ; (\"summary\") -> Dictionary key->Array(value,status,note)\n'   (\"checks\") -> Collection of Array(6) ; (\"sections\") -> Dictionary key -> Dictionary(status,note,rows,cols,types,data)\nPublic Function FetchFullCost() As Object\n    Set FetchFullCost = ParseExport(HttpGetText(BuildExportUrl()))\nEnd Function\n\nPublic Function ParseExport(ByVal text As String) As Object\n    Dim result As Object, meta As Object, summary As Object, sections As Object, checks As Collection\n    Dim lines() As String\n    Dim i As Long, mode As String\n    Dim f() As String\n    Dim sec As Object\n    Dim nRows As Long, nCols As Long, r As Long, c As Long\n    Dim colSpec() As String, types() As String, heads() As String, keys() As String\n    Dim data() As Variant\n\n    Set result = CreateObject(\"Scripting.Dictionary\")\n    Set meta = CreateObject(\"Scripting.Dictionary\")\n    Set summary = CreateObject(\"Scripting.Dictionary\")\n    Set sections = CreateObject(\"Scripting.Dictionary\")\n    Set checks = New Collection\n    text = Replace(text, vbCr, \"\")\n    lines = Split(text, vbLf)\n    If UBound(lines) < 0 Then Err.Raise vbObjectError + 1, \"ParseExport\", \"Empty export\"\n    f = Split(lines(0), vbTab)\n    If f(0) <> \"##EXPORT\" Then Err.Raise vbObjectError + 2, \"ParseExport\", \"Not a HotelCost export (missing ##EXPORT header)\"\n    result(\"exportVersion\") = f(1)\n    result(\"exportId\") = f(2)\n\n    i = 1\n    Do While i <= UBound(lines)\n        If Left$(lines(i), 2) = \"##\" Then\n            f = Split(lines(i), vbTab)\n            mode = f(0)\n            If mode = \"##END\" Then\n                result(\"complete\") = True\n                Exit Do\n            ElseIf mode = \"##SECTION\" Then\n                Set sec = CreateObject(\"Scripting.Dictionary\")\n                sec(\"key\") = f(1)\n                sec(\"status\") = f(2)\n                nRows = CLng(f(3))\n                If UBound(f) >= 4 Then sec(\"note\") = f(4) Else sec(\"note\") = \"\"\n                i = i + 1\n                colSpec = Split(lines(i), vbTab)\n                nCols = UBound(colSpec) + 1\n                ReDim types(1 To nCols)\n                ReDim heads(1 To nCols)\n                ReDim keys(1 To nCols)\n                For c = 1 To nCols\n                    f = Split(colSpec(c - 1), \":\", 3)\n                    keys(c) = f(0)\n                    types(c) = f(1)\n                    heads(c) = f(2)\n                Next c\n                sec(\"rows\") = nRows\n                sec(\"cols\") = nCols\n                sec(\"types\") = types\n                sec(\"headers\") = heads\n                sec(\"keys\") = keys\n                If nRows > 0 Then\n                    ReDim data(1 To nRows, 1 To nCols)\n                    For r = 1 To nRows\n                        If i + r > UBound(lines) Then Err.Raise vbObjectError + 3, \"ParseExport\", \"Truncated section \" & sec(\"key\")\n                        f = Split(lines(i + r), vbTab)\n                        If UBound(f) + 1 <> nCols Then Err.Raise vbObjectError + 4, \"ParseExport\", \"Column count mismatch in \" & sec(\"key\") & \" row \" & r\n                        For c = 1 To nCols\n                            data(r, c) = ConvertCell(f(c - 1), types(c))\n                        Next c\n                    Next r\n                    sec(\"data\") = data\n                End If\n                sections(sec(\"key\")) = sec\n                i = i + nRows\n            End If\n        ElseIf Len(lines(i)) > 0 Then\n            f = Split(lines(i), vbTab)\n            Select Case mode\n                Case \"##META\"\n                    meta(f(0)) = f(1)\n                Case \"##SUMMARY\"\n                    summary(f(0)) = Array(f(1), f(2), f(3))\n                Case \"##CHECKS\"\n                    checks.Add f\n            End Select\n        End If\n        i = i + 1\n    Loop\n    If Not result.Exists(\"complete\") Then Err.Raise vbObjectError + 5, \"ParseExport\", \"Export truncated (no ##END marker) - incomplete data is never written.\"\n    Set result(\"meta\") = meta\n    Set result(\"summary\") = summary\n    Set result(\"sections\") = sections\n    Set result(\"checks\") = checks\n    Set ParseExport = result\nEnd Function\n\nPublic Function ConvertCell(ByVal s As String, ByVal colType As String) As Variant\n    If Len(s) = 0 Then\n        ConvertCell = Empty\n        Exit Function\n    End If\n    Select Case colType\n        Case \"int\", \"qty\", \"money\", \"unitcost\", \"pct\"\n            ConvertCell = Val(s)\n        Case \"date\"\n            ConvertCell = DateSerial(CInt(Mid$(s, 1, 4)), CInt(Mid$(s, 6, 2)), CInt(Mid$(s, 9, 2)))\n        Case \"datetime\"\n            ConvertCell = DateSerial(CInt(Mid$(s, 1, 4)), CInt(Mid$(s, 6, 2)), CInt(Mid$(s, 9, 2))) + _\n                          TimeSerial(CInt(Mid$(s, 12, 2)), CInt(Mid$(s, 15, 2)), CInt(Mid$(s, 18, 2)))\n        Case Else\n            ' neutralise spreadsheet formula injection from source data\n            If InStr(1, \"=+-@\", Left$(s, 1)) > 0 Then ConvertCell = \"'\" & s Else ConvertCell = s\n    End Select\nEnd Function\n",
  "modDepartmentCost": "'==============================================================================\n' modDepartmentCost :: Department, outlet, cost center, allocation, budget, forecast, saving, missing data\n' By design the cost calculations for this area run on the HotelCost server (one\n' cost engine shared with the web application, spec 149). This module only lists\n' the datasets of its area so modReport writes them in a predictable order.\n'==============================================================================\nOption Explicit\n\nPublic Function DepartmentSections() As Variant\n    DepartmentSections = Array(\"departmentCost\", \"outletCost\", \"costCenter\", \"costAllocation\", \"budgetVariance\", \"forecast\", \"costSaving\", \"missingData\", \"rawSales\")\nEnd Function\n",
  "modErrorHandling": "'==============================================================================\n' modErrorHandling :: EXPORT_ERRORS and RUN_LOG. Errors are recorded, never hidden.\n'==============================================================================\nOption Explicit\n\nPublic Sub LogError(ByVal moduleName As String, ByVal record As String, ByVal errType As String, ByVal description As String, ByVal severity As String)\n    Dim lo As ListObject\n    Dim rw As ListRow\n    If severity = \"CRITICAL\" Or severity = \"HIGH\" Then gErrors = gErrors + 1 Else gWarnings = gWarnings + 1\n    Set lo = FindTable(\"tbl_errors\")\n    If lo Is Nothing Then Exit Sub\n    lo.Parent.Unprotect \"\"\n    Set rw = lo.ListRows.Add\n    rw.Range.Value = Array(Now, gRunId, moduleName, record, errType, description, severity)\nEnd Sub\n\nPublic Sub LogRun(ByVal startedAt As Date, ByVal runStatus As String, ByVal records As Long)\n    Dim lo As ListObject\n    Dim rw As ListRow\n    Set lo = FindTable(\"tbl_runLog\")\n    If lo Is Nothing Then Exit Sub\n    lo.Parent.Unprotect \"\"\n    Set rw = lo.ListRows.Add\n    rw.Range.Value = Array(gRunId, Date, Application.UserName, CStr(CtlValue(\"ctl_Hotel\")), CStr(CtlValue(\"ctl_PeriodLabel\")), _\n                           startedAt, Now, runStatus, records, gErrors, gWarnings)\nEnd Sub\n\nPublic Sub MarkRunStatus(ByVal runStatus As String)\n    Dim c As Range\n    Set c = ThisWorkbook.Names(\"ctl_RunStatus\").RefersToRange\n    c.Parent.Unprotect \"\"\n    c.Value = runStatus & \"  (\" & Format$(Now, \"yyyy-mm-dd hh:nn\") & \")\"\n    Select Case runStatus\n        Case \"EXPORT COMPLETED SUCCESSFULLY\": c.Interior.Color = RGB(214, 245, 227)\n        Case \"EXPORT COMPLETED WITH WARNINGS\": c.Interior.Color = RGB(254, 243, 199)\n        Case Else: c.Interior.Color = RGB(254, 226, 226)\n    End Select\nEnd Sub\n",
  "modFormatting": "'==============================================================================\n' modFormatting :: protection, layout and the CONTROL button.\n'==============================================================================\nOption Explicit\n\nPublic Sub UnprotectAll()\n    Dim ws As Worksheet\n    For Each ws In ThisWorkbook.Worksheets\n        ws.Unprotect \"\"\n    Next ws\nEnd Sub\n\n' Report, raw and calculation sheets are protected (no password: this prevents accidental\n' edits, it is not a security boundary). Filtering and pivots stay usable.\nPublic Sub ProtectAll()\n    Dim ws As Worksheet\n    For Each ws In ThisWorkbook.Worksheets\n        ws.Protect Password:=\"\", DrawingObjects:=True, Contents:=True, UserInterfaceOnly:=True, _\n                   AllowFiltering:=True, AllowSorting:=True, AllowUsingPivotTables:=True, AllowFormattingColumns:=True\n    Next ws\nEnd Sub\n\nPublic Sub FormatWorkbook()\n    Dim ws As Worksheet\n    Dim lo As ListObject\n    Dim c As Range\n    For Each ws In ThisWorkbook.Worksheets\n        If ws.Visible = -1 Then\n            For Each lo In ws.ListObjects\n                lo.Range.Columns.AutoFit\n                For Each c In lo.HeaderRowRange.Cells\n                    If c.ColumnWidth > 60 Then c.ColumnWidth = 60\n                    If c.ColumnWidth < 10 Then c.ColumnWidth = 10\n                Next c\n            Next lo\n        End If\n    Next ws\nEnd Sub\n\nPublic Function ButtonCaption() As String\n    ' \"TUM COST RAPORLARINI OLUSTUR\" with Turkish letters (U+00DC, U+015E)\n    ButtonCaption = \"T\" & ChrW(&HDC) & \"M COST RAPORLARINI OLU\" & ChrW(&H15E) & \"TUR\" & vbLf & \"GENERATE FULL COST REPORT\"\nEnd Function\n\n' The packaged workbook already contains the button; this re-creates it if a user deleted it.\nPublic Sub EnsureControlButton()\n    Dim ws As Worksheet\n    Dim shp As Shape\n    Dim exists As Boolean\n    Set ws = ThisWorkbook.Worksheets(CONTROL_SHEET)\n    For Each shp In ws.Shapes\n        If shp.Name = \"btnGenerate\" Or shp.OnAction Like \"*GenerateFullCostReport\" Then exists = True\n    Next shp\n    If exists Then Exit Sub\n    ws.Unprotect \"\"\n    Set shp = ws.Shapes.AddShape(5, ws.Range(\"F4\").Left, ws.Range(\"F4\").Top, 330, 70)\n    shp.Name = \"btnGenerate\"\n    shp.OnAction = \"GenerateFullCostReport\"\n    shp.Fill.ForeColor.RGB = RGB(21, 132, 89)\n    shp.Line.Visible = False\n    With shp.TextFrame2.TextRange\n        .Text = ButtonCaption()\n        .Font.Bold = True\n        .Font.Size = 14\n        .Font.Fill.ForeColor.RGB = RGB(255, 255, 255)\n        .ParagraphFormat.Alignment = 2\n    End With\n    shp.TextFrame2.VerticalAnchor = 3\nEnd Sub\n",
  "modInventory": "'==============================================================================\n' modInventory :: Inventory value, monthly stock, counts, critical/aging stock, reorder, purchasing, supplier prices, PPV, raw ledger\n' By design the cost calculations for this area run on the HotelCost server (one\n' cost engine shared with the web application, spec 149). This module only lists\n' the datasets of its area so modReport writes them in a predictable order.\n'==============================================================================\nOption Explicit\n\nPublic Function InventorySections() As Variant\n    InventorySections = Array(\"inventoryValue\", \"monthlyStock\", \"stockVariance\", \"criticalStock\", \"stockAging\", \"reorder\", \"purchaseCost\", \"supplierPrice\", \"ppv\", \"rawProducts\", \"rawStockTransactions\")\nEnd Function\n",
  "modMain": "'==============================================================================\n' HotelCost - Full Cost Report workbook :: modMain\n' Entry points. All cost figures are calculated by the HotelCost server (one cost\n' engine shared with the web application). This VBA project only fetches the\n' authenticated export, writes it into tables, refreshes pivots/charts and runs\n' reconciliation. It never stores credentials in the workbook.\n'==============================================================================\nOption Explicit\n\nPublic Const WORKBOOK_VERSION As String = \"1.0.0\"\nPublic Const EXPORT_SCHEMA_MAJOR As String = \"1\"\n\nPublic gRunId As String\nPublic gWarnings As Long\nPublic gErrors As Long\nPublic gRecords As Long\n\nPrivate Const XL_CALC_MANUAL As Long = -4135\n\n' Main button: \"TUM COST RAPORLARINI OLUSTUR\" / \"GENERATE FULL COST REPORT\"\nPublic Sub GenerateFullCostReport()\n    Dim mode As String\n    mode = LCase$(Trim$(CStr(CtlValue(\"ctl_RefreshMode\"))))\n    RunPipeline (mode = \"full rebuild\")\nEnd Sub\n\nPublic Sub RefreshCurrentPeriod()\n    RunPipeline False\nEnd Sub\n\nPublic Sub FullRebuild()\n    RunPipeline True\nEnd Sub\n\nPrivate Sub RunPipeline(ByVal fullRebuild As Boolean)\n    Dim t0 As Date\n    Dim payload As Object\n    Dim stage As String\n    Dim prevCalc As Long\n    Dim prevEvents As Boolean\n    Dim finalStatus As String\n\n    gRunId = Format$(Now, \"yyyymmdd-hhnnss\")\n    gWarnings = 0\n    gErrors = 0\n    gRecords = 0\n    t0 = Now\n    prevCalc = Application.Calculation\n    prevEvents = Application.EnableEvents\n\n    On Error GoTo Fail\n    Application.ScreenUpdating = False\n    Application.EnableEvents = False\n    Application.Calculation = XL_CALC_MANUAL\n\n    stage = \"Read & validate control parameters\"\n    Status stage\n    If Not ValidateParameters() Then\n        finalStatus = \"EXPORT FAILED\"\n        GoTo Finish\n    End If\n\n    stage = \"Fetch data from HotelCost API\"\n    Status stage\n    Set payload = FetchFullCost()\n\n    stage = \"Validate raw data\"\n    Status stage\n    If Not ValidateExport(payload) Then\n        finalStatus = \"EXPORT FAILED\"\n        GoTo Finish\n    End If\n\n    UnprotectAll\n    If fullRebuild Then\n        stage = \"Full rebuild: clear generated tables\"\n        Status stage\n        ClearGeneratedTables\n    End If\n\n    stage = \"Write raw data, calculations and reports\"\n    Status stage\n    gRecords = WriteAllSections(payload)\n    WriteMetadata payload\n\n    stage = \"Refresh pivot tables\"\n    Status stage\n    RefreshPivots\n\n    stage = \"Refresh charts\"\n    Status stage\n    RefreshCharts\n\n    stage = \"Run reconciliation\"\n    Status stage\n    Application.Calculate\n    RunReconciliation payload\n\n    stage = \"Format workbook\"\n    Status stage\n    FormatWorkbook\n    ProtectAll\n\n    If gErrors > 0 Then\n        finalStatus = \"EXPORT FAILED\"\n    ElseIf gWarnings > 0 Then\n        finalStatus = \"EXPORT COMPLETED WITH WARNINGS\"\n    Else\n        finalStatus = \"EXPORT COMPLETED SUCCESSFULLY\"\n    End If\n    GoTo Finish\n\nFail:\n    LogError \"modMain\", stage, \"RUNTIME\", Err.Number & \": \" & Err.Description, \"CRITICAL\"\n    finalStatus = \"EXPORT FAILED\"\n    Resume Finish\n\nFinish:\n    On Error Resume Next\n    ' Never leave Excel in a broken state (spec 83): restore application settings.\n    Application.Calculation = prevCalc\n    Application.EnableEvents = prevEvents\n    Application.ScreenUpdating = True\n    Application.StatusBar = False\n    On Error GoTo 0\n    MarkRunStatus finalStatus\n    LogRun t0, finalStatus, gRecords\n    ThisWorkbook.Worksheets(CONTROL_SHEET).Activate\n    MsgBox finalStatus & vbCrLf & vbCrLf & CompletionSummary(payload), _\n        IIf(finalStatus = \"EXPORT FAILED\", vbCritical, IIf(gWarnings > 0, vbExclamation, vbInformation)), \"HotelCost\"\nEnd Sub\n\nPublic Sub ExportManagementPdf()\n    Dim names As Variant\n    Dim target As String\n    Dim folder As String\n    On Error GoTo Fail\n    names = Array(CONTROL_SHEET, \"02_EXECUTIVE_SUMMARY\", \"04_FOOD_COST\", \"05_BEVERAGE_COST\", \"09_CONSUMPTION_VARIANCE\", _\n                  \"11_WASTE_SUMMARY\", \"34_DEPARTMENT_COST\", \"45_UNEXPLAINED_VARIANCE\", \"46_RECONCILIATION\", \"53_DASHBOARD_CHARTS\")\n    folder = ThisWorkbook.Path\n    If Len(folder) = 0 Then folder = Environ$(\"TEMP\")\n    target = folder & Application.PathSeparator & \"HotelCost_Management_Report_\" & _\n             Format$(CtlValue(\"ctl_StartDate\"), \"yyyy_mm\") & \".pdf\"\n    ThisWorkbook.Worksheets(names).Select\n    ActiveSheet.ExportAsFixedFormat 0, target, 0, True, False, , , True\n    ThisWorkbook.Worksheets(CONTROL_SHEET).Select\n    Exit Sub\nFail:\n    LogError \"modMain\", \"ExportManagementPdf\", \"PDF\", Err.Number & \": \" & Err.Description, \"HIGH\"\n    MsgBox \"PDF export failed: \" & Err.Description, vbCritical, \"HotelCost\"\nEnd Sub\n\nPublic Function CtlValue(ByVal rangeName As String) As Variant\n    CtlValue = ThisWorkbook.Names(rangeName).RefersToRange.Value\nEnd Function\n\nPublic Sub SetCtl(ByVal rangeName As String, ByVal v As Variant)\n    ThisWorkbook.Names(rangeName).RefersToRange.Value = v\nEnd Sub\n\nPublic Sub Status(ByVal msg As String)\n    Application.StatusBar = \"HotelCost: \" & msg & \" ...\"\n    DoEvents\nEnd Sub\n",
  "modMinibar": "'==============================================================================\n' modMinibar :: Minibar cost (module NOT_AVAILABLE until Phase 2; headers only)\n' By design the cost calculations for this area run on the HotelCost server (one\n' cost engine shared with the web application, spec 149). This module only lists\n' the datasets of its area so modReport writes them in a predictable order.\n'==============================================================================\nOption Explicit\n\nPublic Function MinibarSections() As Variant\n    MinibarSections = Array(\"minibarCost\")\nEnd Function\n",
  "modPivot": "'==============================================================================\n' modPivot :: rebuilds the pivot tables on 55_PIVOTS from the report tables.\n'==============================================================================\nOption Explicit\n\nPrivate Const XL_DATABASE As Long = 1\nPrivate Const XL_ROW_FIELD As Long = 1\nPrivate Const XL_SUM As Long = -4157\nPrivate Const PIVOT_SHEET As String = \"55_PIVOTS\"\n\nPublic Sub RefreshPivots()\n    Dim ws As Worksheet\n    Dim pt As PivotTable\n    Set ws = ThisWorkbook.Worksheets(PIVOT_SHEET)\n    For Each pt In ws.PivotTables\n        pt.TableRange2.Clear\n    Next pt\n    ws.Range(\"A6:AZ2000\").Clear\n    MakePivot ws, \"tbl_costDetail\", ws.Range(\"A8\"), \"pvtDepartmentCost\", \"Department\", \"Total Cost\", \"Department Cost\"\n    MakePivot ws, \"tbl_costDetail\", ws.Range(\"E8\"), \"pvtCategoryCost\", \"Category\", \"Total Cost\", \"Category Cost\"\n    MakePivot ws, \"tbl_costDetail\", ws.Range(\"I8\"), \"pvtSupplierCost\", \"Supplier\", \"Total Cost\", \"Supplier Cost\"\n    MakePivot ws, \"tbl_costDetail\", ws.Range(\"M8\"), \"pvtProductCost\", \"Product\", \"Total Cost\", \"Product Cost\"\n    MakePivot ws, \"tbl_waste\", ws.Range(\"Q8\"), \"pvtWaste\", \"Waste Type\", \"Waste Cost\", \"Waste by Type\"\n    MakePivot ws, \"tbl_inventoryValue\", ws.Range(\"U8\"), \"pvtStock\", \"Category\", \"Stock Value\", \"Stock Value by Category\"\n    MakePivot ws, \"tbl_recipeSummary\", ws.Range(\"Y8\"), \"pvtRecipeCost\", \"Type\", \"Total Cost / Batch\", \"Recipe Cost by Type\"\n    MakePivot ws, \"tbl_buffetCost\", ws.Range(\"AC8\"), \"pvtBuffetCost\", \"Meal\", \"Food Cost\", \"Buffet Cost by Meal\"\n    MakePivot ws, \"tbl_minibarCost\", ws.Range(\"AG8\"), \"pvtMinibarCost\", \"Room\", \"Cost\", \"Minibar Cost by Room\"\n    ws.Range(\"AK7\").Value = \"Room cost pivot: module not yet available (NOT_AVAILABLE).\"\n    ws.Range(\"AK7\").Font.Italic = True\nEnd Sub\n\nPrivate Sub MakePivot(ByVal ws As Worksheet, ByVal src As String, ByVal dest As Range, ByVal pivotName As String, _\n                      ByVal rowField As String, ByVal dataField As String, ByVal title As String)\n    Dim lo As ListObject\n    Dim pc As PivotCache\n    Dim pt As PivotTable\n    On Error GoTo Fail\n    Set lo = FindTable(src)\n    If lo Is Nothing Then Exit Sub\n    dest.Offset(-1, 0).Value = title\n    dest.Offset(-1, 0).Font.Bold = True\n    Set pc = ThisWorkbook.PivotCaches.Create(SourceType:=XL_DATABASE, SourceData:=src)\n    Set pt = pc.CreatePivotTable(TableDestination:=dest, TableName:=pivotName)\n    pt.PivotFields(rowField).Orientation = XL_ROW_FIELD\n    pt.AddDataField pt.PivotFields(dataField), \"Sum of \" & dataField, XL_SUM\n    pt.DataBodyRange.NumberFormat = \"#,##0.00\"\n    pt.RefreshTable\n    Exit Sub\nFail:\n    LogError \"modPivot\", pivotName, \"PIVOT\", Err.Number & \": \" & Err.Description, \"WARNING\"\nEnd Sub\n",
  "modRecipeCost": "'==============================================================================\n' modRecipeCost :: Recipe cost explosion, recipe summary, recipe trend, yield, portion control\n' By design the cost calculations for this area run on the HotelCost server (one\n' cost engine shared with the web application, spec 149). This module only lists\n' the datasets of its area so modReport writes them in a predictable order.\n'==============================================================================\nOption Explicit\n\nPublic Function RecipeSections() As Variant\n    RecipeSections = Array(\"recipeSummary\", \"recipeCost\", \"recipeTrend\", \"yield\", \"portionVariance\")\nEnd Function\n",
  "modReconciliation": "'==============================================================================\n' modReconciliation :: export QA after every run (spec 78, 129-131, 144-145).\n'  1. server-side checks (same engine as the app) -> tbl_serverChecks\n'  2. workbook formula checks (tbl_excelChecks, live formulas over the tables)\n'  3. VBA checks: row counts vs export, duplicate trace ids -> tbl_vbaChecks\n'==============================================================================\nOption Explicit\n\nPublic Sub RunReconciliation(ByVal payload As Object)\n    Dim lo As ListObject\n    Dim data() As Variant\n    Dim chk As Variant\n    Dim i As Long\n    Dim nFail As Long, nWarn As Long\n    Dim vba As Collection\n    Dim k As Variant\n    Dim sec As Object\n    Dim t As ListObject\n    Dim actual As Long\n\n    ' 1) server checks\n    Set lo = FindTable(\"tbl_serverChecks\")\n    If Not lo Is Nothing And payload(\"checks\").Count > 0 Then\n        ReDim data(1 To payload(\"checks\").Count, 1 To 6)\n        i = 0\n        For Each chk In payload(\"checks\")\n            i = i + 1\n            data(i, 1) = chk(0)\n            data(i, 2) = ConvertCell(chk(1), \"money\")\n            data(i, 3) = ConvertCell(chk(2), \"money\")\n            data(i, 4) = ConvertCell(chk(3), \"money\")\n            data(i, 5) = chk(4)\n            data(i, 6) = chk(5)\n            If chk(4) = \"FAIL\" Then nFail = nFail + 1\n            If chk(4) = \"WARNING\" Then nWarn = nWarn + 1\n        Next chk\n        If Not lo.DataBodyRange Is Nothing Then lo.DataBodyRange.ClearContents\n        lo.Resize lo.HeaderRowRange.Resize(payload(\"checks\").Count + 1)\n        lo.DataBodyRange.Value = data\n    End If\n\n    ' 3) VBA checks: every table has exactly the rows the export declared; no duplicate trace ids\n    Set vba = New Collection\n    For Each k In payload(\"sections\").Keys\n        Set sec = payload(\"sections\")(k)\n        Set t = FindTable(\"tbl_\" & k)\n        If Not t Is Nothing Then\n            If sec(\"rows\") = 0 Then actual = 0 Else actual = t.ListRows.Count\n            vba.Add Array(\"Row count \" & k, sec(\"rows\"), actual, IIf(actual = sec(\"rows\"), \"PASS\", \"FAIL\"))\n        End If\n    Next k\n    vba.Add DuplicateCheck(\"tbl_costDetail\", \"Trace ID\")\n    vba.Add DuplicateCheck(\"tbl_rawStockTransactions\", \"Transaction ID\")\n    Set lo = FindTable(\"tbl_vbaChecks\")\n    If Not lo Is Nothing Then\n        ReDim data(1 To vba.Count, 1 To 4)\n        For i = 1 To vba.Count\n            data(i, 1) = vba(i)(0): data(i, 2) = vba(i)(1): data(i, 3) = vba(i)(2): data(i, 4) = vba(i)(3)\n            If vba(i)(3) = \"FAIL\" Then nFail = nFail + 1\n        Next i\n        If Not lo.DataBodyRange Is Nothing Then lo.DataBodyRange.ClearContents\n        lo.Resize lo.HeaderRowRange.Resize(vba.Count + 1)\n        lo.DataBodyRange.Value = data\n    End If\n\n    ' 2) workbook formula checks\n    Application.Calculate\n    Set lo = FindTable(\"tbl_excelChecks\")\n    If Not lo Is Nothing Then\n        If Not lo.DataBodyRange Is Nothing Then\n            For i = 1 To lo.ListRows.Count\n                Select Case CStr(lo.ListColumns(\"Status\").DataBodyRange.Cells(i, 1).Value)\n                    Case \"FAIL\": nFail = nFail + 1\n                    Case \"WARNING\": nWarn = nWarn + 1\n                End Select\n            Next i\n        End If\n    End If\n\n    If nFail > 0 Then LogError \"modReconciliation\", \"checks\", \"RECONCILIATION\", nFail & \" reconciliation check(s) failed - see 46_RECONCILIATION\", \"HIGH\"\n    SetCtl \"ctl_ScoreDataQuality\", payload(\"meta\")(\"dataQuality\")\n    SetCtl \"ctl_ScoreRecon\", IIf(nFail > 0, \"FAIL\", IIf(nWarn > 0, \"WARNING\", \"PASS\"))\n    SetCtl \"ctl_ScoreWarnings\", nWarn\n    SetCtl \"ctl_ScoreErrors\", nFail\n    gWarnings = gWarnings + nWarn\nEnd Sub\n\nPrivate Function DuplicateCheck(ByVal tableName As String, ByVal colName As String) As Variant\n    Dim lo As ListObject\n    Dim seen As Object\n    Dim v As Variant\n    Dim r As Long, dup As Long\n    Set lo = FindTable(tableName)\n    If lo Is Nothing Then\n        DuplicateCheck = Array(\"Duplicates \" & tableName, 0, 0, \"WARNING\")\n        Exit Function\n    End If\n    Set seen = CreateObject(\"Scripting.Dictionary\")\n    If Not lo.DataBodyRange Is Nothing Then\n        v = lo.ListColumns(colName).DataBodyRange.Value\n        If IsArray(v) Then\n            For r = 1 To UBound(v, 1)\n                If Len(CStr(v(r, 1))) > 0 Then\n                    If seen.Exists(CStr(v(r, 1))) Then dup = dup + 1 Else seen.Add CStr(v(r, 1)), True\n                End If\n            Next r\n        End If\n    End If\n    DuplicateCheck = Array(\"Duplicate \" & colName & \" in \" & tableName, 0, dup, IIf(dup = 0, \"PASS\", \"FAIL\"))\nEnd Function\n",
  "modReport": "'==============================================================================\n' modReport :: bulk writer. Each export section maps 1:1 to an Excel Table named\n' \"tbl_<sectionKey>\". Data is written as one 2-D array per table (no cell loops).\n'==============================================================================\nOption Explicit\n\nPublic Const CONTROL_SHEET As String = \"01_CONTROL\"\n\nPublic Function FindTable(ByVal tableName As String) As ListObject\n    Dim ws As Worksheet\n    Dim lo As ListObject\n    For Each ws In ThisWorkbook.Worksheets\n        For Each lo In ws.ListObjects\n            If StrComp(lo.Name, tableName, vbTextCompare) = 0 Then\n                Set FindTable = lo\n                Exit Function\n            End If\n        Next lo\n    Next ws\n    Set FindTable = Nothing\nEnd Function\n\n' Area order mirrors the workbook structure; remaining sections are written generically.\nPublic Function WriteAllSections(ByVal payload As Object) As Long\n    Dim done As Object\n    Dim areas As Variant\n    Dim area As Variant\n    Dim k As Variant\n    Dim n As Long\n    Set done = CreateObject(\"Scripting.Dictionary\")\n    areas = Array(CostSections(), RecipeSections(), InventorySections(), WasteSections(), _\n                  BuffetSections(), MinibarSections(), RoomSections(), DepartmentSections())\n    For Each area In areas\n        For Each k In area\n            If payload(\"sections\").Exists(CStr(k)) And Not done.Exists(CStr(k)) Then\n                n = n + WriteSection(CStr(k), payload(\"sections\")(CStr(k)))\n                done(CStr(k)) = True\n            End If\n        Next k\n    Next area\n    For Each k In payload(\"sections\").Keys\n        If Not done.Exists(CStr(k)) Then\n            n = n + WriteSection(CStr(k), payload(\"sections\")(CStr(k)))\n            done(CStr(k)) = True\n        End If\n    Next k\n    WriteAllSections = n\nEnd Function\n\nPublic Function WriteSection(ByVal key As String, ByVal sec As Object) As Long\n    Dim lo As ListObject\n    Dim heads As Variant\n    Dim c As Long\n    Dim nRows As Long\n    Dim statusCell As Range\n    Dim note As String\n\n    Set lo = FindTable(\"tbl_\" & key)\n    If lo Is Nothing Then\n        LogError \"modReport\", key, \"MISSING_TABLE\", \"Workbook has no table tbl_\" & key & \" (export is newer than workbook?).\", \"WARNING\"\n        Exit Function\n    End If\n    heads = sec(\"headers\")\n    If lo.ListColumns.Count <> sec(\"cols\") Then\n        LogError \"modReport\", key, \"SCHEMA\", \"Column count differs: workbook \" & lo.ListColumns.Count & \" vs export \" & sec(\"cols\"), \"HIGH\"\n        Exit Function\n    End If\n    For c = 1 To sec(\"cols\")\n        If lo.ListColumns(c).Name <> heads(c) Then\n            LogError \"modReport\", key, \"SCHEMA\", \"Column \" & c & \" is '\" & lo.ListColumns(c).Name & \"' but export sends '\" & heads(c) & \"'\", \"HIGH\"\n            Exit Function\n        End If\n    Next c\n\n    nRows = sec(\"rows\")\n    ' Duplicate protection: the table is cleared before writing, so a refresh never appends twice.\n    If Not lo.DataBodyRange Is Nothing Then lo.DataBodyRange.ClearContents\n    If nRows = 0 Then\n        lo.Resize lo.HeaderRowRange.Resize(2)\n    Else\n        lo.Resize lo.HeaderRowRange.Resize(nRows + 1)\n        lo.DataBodyRange.Value = sec(\"data\")\n    End If\n\n    Set statusCell = lo.HeaderRowRange.Cells(1, 1).Offset(-2, 0)\n    note = CStr(sec(\"note\"))\n    statusCell.Value = \"Data status: \" & sec(\"status\") & IIf(Len(note) > 0, \" - \" & note, \"\") & \"  |  rows: \" & nRows\n    If sec(\"status\") = \"NOT_AVAILABLE\" Then statusCell.Font.Color = RGB(180, 83, 9) Else statusCell.Font.Color = RGB(80, 92, 120)\n    WriteSection = nRows\nEnd Function\n\n' Full rebuild: clears generated tables only. Manual notes, CONTROL inputs, run log\n' and error history are preserved (safe refresh).\nPublic Sub ClearGeneratedTables()\n    Dim ws As Worksheet\n    Dim lo As ListObject\n    For Each ws In ThisWorkbook.Worksheets\n        For Each lo In ws.ListObjects\n            If Left$(lo.Name, 4) = \"tbl_\" And Not IsStaticTable(lo.Name) Then\n                If Not lo.DataBodyRange Is Nothing Then lo.DataBodyRange.ClearContents\n                lo.Resize lo.HeaderRowRange.Resize(2)\n            End If\n        Next lo\n    Next ws\nEnd Sub\n\n' Tables that are not datasets: logs, formula checks, lists, documentation.\nPrivate Function IsStaticTable(ByVal n As String) As Boolean\n    Select Case LCase$(n)\n        Case \"tbl_runlog\", \"tbl_errors\", \"tbl_excelchecks\", \"tbl_formulas\", \"tbl_sourcemap\"\n            IsStaticTable = True\n        Case Else\n            IsStaticTable = (LCase$(Left$(n, 7)) = \"tbl_lst\")\n    End Select\nEnd Function\n\nPublic Sub WriteMetadata(ByVal payload As Object)\n    Dim m As Object\n    Set m = payload(\"meta\")\n    SetCtl \"ctl_Hotel\", m(\"hotel\")\n    SetCtl \"ctl_Currency\", m(\"currency\")\n    SetCtl \"ctl_PeriodLabel\", m(\"periodLabel\")\n    SetCtl \"ctl_GeneratedAt\", m(\"generatedAt\")\n    SetCtl \"ctl_GeneratedBy\", m(\"generatedBy\") & \" (Excel user: \" & Application.UserName & \")\"\n    SetCtl \"ctl_DataThrough\", m(\"dataThrough\")\n    SetCtl \"ctl_ExportId\", payload(\"exportId\")\n    SetCtl \"ctl_ExportVersion\", payload(\"exportVersion\")\n    SetCtl \"ctl_AppVersion\", m(\"appVersion\")\n    SetCtl \"ctl_ContentHash\", m(\"contentHash\")\n    SetCtl \"ctl_WorkbookVersion\", WORKBOOK_VERSION\nEnd Sub\n\nPublic Function CompletionSummary(ByVal payload As Object) As String\n    Dim keys As Variant, labels As Variant\n    Dim i As Long\n    Dim s As String\n    If payload Is Nothing Then\n        CompletionSummary = \"No data was written. See 48_EXPORT_ERRORS.\"\n        Exit Function\n    End If\n    keys = Array(\"costDetail\", \"rawStockTransactions\", \"actualConsumption\", \"waste\", \"recipeSummary\", \"rawSales\", \"inventoryValue\")\n    labels = Array(\"cost records\", \"stock transactions\", \"consumption records\", \"waste records\", \"recipes\", \"sales lines\", \"stock positions\")\n    For i = 0 To UBound(keys)\n        If payload(\"sections\").Exists(keys(i)) Then\n            s = s & ChrW(&H2714) & \" \" & Format$(payload(\"sections\")(keys(i))(\"rows\"), \"#,##0\") & \" \" & labels(i) & vbCrLf\n        End If\n    Next i\n    s = s & vbCrLf & \"Data quality: \" & CStr(CtlValue(\"ctl_ScoreDataQuality\")) & \"%\" & vbCrLf & _\n        \"Reconciliation: \" & CStr(CtlValue(\"ctl_ScoreRecon\")) & vbCrLf & _\n        \"Warnings: \" & gWarnings & vbCrLf & \"Errors: \" & gErrors\n    CompletionSummary = s\nEnd Function\n",
  "modRoomCost": "'==============================================================================\n' modRoomCost :: Room, housekeeping, laundry, labor, energy, engineering (server-calculated, Phase 3)\n' By design the cost calculations for this area run on the HotelCost server (one\n' cost engine shared with the web application, spec 149). This module only lists\n' the datasets of its area so modReport writes them in a predictable order.\n'==============================================================================\nOption Explicit\n\nPublic Function RoomSections() As Variant\n    RoomSections = Array(\"roomCost\", \"roomTypeCost\", \"roomFloorCost\", \"roomChannelCost\", \"housekeepingCost\", \"laundryCost\", \"linenCost\", \"laborCost\", \"energyCost\", \"meterReadings\", \"engineeringCost\", \"assetCost\")\nEnd Function\n",
  "modValidation": "'==============================================================================\n' modValidation :: control parameters and raw export validation.\n'==============================================================================\nOption Explicit\n\nPublic Function ValidateParameters() As Boolean\n    Dim url As String\n    Dim d1 As Variant, d2 As Variant\n    ValidateParameters = False\n    url = LCase$(Trim$(CStr(CtlValue(\"ctl_ApiUrl\"))))\n    If Not (Left$(url, 8) = \"https://\" Or Left$(url, 16) = \"http://localhost\" Or Left$(url, 16) = \"http://127.0.0.1\") Then\n        LogError \"modValidation\", \"ctl_ApiUrl\", \"PARAMETER\", \"API URL must use HTTPS (or localhost for testing).\", \"CRITICAL\"\n        Exit Function\n    End If\n    If Len(Trim$(CStr(CtlValue(\"ctl_HotelId\")))) = 0 Then\n        LogError \"modValidation\", \"ctl_HotelId\", \"PARAMETER\", \"Hotel is missing.\", \"CRITICAL\"\n        Exit Function\n    End If\n    d1 = CtlValue(\"ctl_StartDate\")\n    d2 = CtlValue(\"ctl_EndDate\")\n    If Not IsDate(d1) Or Not IsDate(d2) Then\n        LogError \"modValidation\", \"dates\", \"PARAMETER\", \"Start and end date must be valid dates.\", \"CRITICAL\"\n        Exit Function\n    End If\n    If CDate(d2) < CDate(d1) Then\n        LogError \"modValidation\", \"dates\", \"PARAMETER\", \"End date is before start date.\", \"CRITICAL\"\n        Exit Function\n    End If\n    If CDate(d2) - CDate(d1) > 366 Then\n        LogError \"modValidation\", \"dates\", \"PARAMETER\", \"Period longer than 366 days is not supported in one workbook.\", \"CRITICAL\"\n        Exit Function\n    End If\n    ValidateParameters = True\nEnd Function\n\nPublic Function ValidateExport(ByVal payload As Object) As Boolean\n    Dim meta As Object\n    Dim required As Variant\n    Dim k As Variant\n    ValidateExport = False\n    If Split(payload(\"exportVersion\"), \".\")(0) <> EXPORT_SCHEMA_MAJOR Then\n        LogError \"modValidation\", \"exportVersion\", \"SCHEMA\", \"Export schema \" & payload(\"exportVersion\") & \" is not supported by workbook \" & WORKBOOK_VERSION & \". Download a new workbook.\", \"CRITICAL\"\n        Exit Function\n    End If\n    Set meta = payload(\"meta\")\n    If meta(\"hotelId\") <> CStr(CtlValue(\"ctl_HotelId\")) Then\n        LogError \"modValidation\", \"hotelId\", \"SCHEMA\", \"Export hotel does not match the CONTROL sheet hotel.\", \"CRITICAL\"\n        Exit Function\n    End If\n    required = Array(\"executiveSummary\", \"costDetail\", \"consumptionVariance\", \"monthlyStock\", \"recipeCost\", \"waste\", \"inventoryValue\", \"departmentCost\")\n    For Each k In required\n        If Not payload(\"sections\").Exists(CStr(k)) Then\n            LogError \"modValidation\", CStr(k), \"SCHEMA\", \"Required section missing from export.\", \"CRITICAL\"\n            Exit Function\n        End If\n    Next k\n    ValidateExport = True\nEnd Function\n",
  "modWaste": "'==============================================================================\n' modWaste :: Waste detail and summaries\n' By design the cost calculations for this area run on the HotelCost server (one\n' cost engine shared with the web application, spec 149). This module only lists\n' the datasets of its area so modReport writes them in a predictable order.\n'==============================================================================\nOption Explicit\n\nPublic Function WasteSections() As Variant\n    WasteSections = Array(\"waste\", \"wasteSummary\", \"wasteByCategory\", \"wasteByDepartment\", \"topWaste\")\nEnd Function\n",
};
